	public function actionPlaceorders()
	{

		$connection = \Yii::$app->db;
		$uid = Yii::$app->user->Id; 
        $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
    	$sql = "SELECT * FROM cart where status=0 and Project=".$projuser->projectid." GROUP BY Project ORDER BY cartID ASC";

  		$command = $connection->createCommand($sql);
	   	$dataReader = $command->query();  
	  	$carts = $dataReader->readAll();


	  	$recart='';
	  	foreach($carts as $cart){

	  		$projname=Projects::findOne($cart['Project']);
	  		

	  		$recart.= '<table class="table table-bordered indent-table">
						
						<thead>
							<tr><td colspan="10" style="background-color: #ecedef;padding-top: 6px;
    padding-bottom: 7px;"><label id='.$projname->Project_Id.' style="
    margin-bottom: 0px !important;margin-left: -6px;
">'.$projname->Name.'</label></td></tr></thead>

	  		<!-- <label style="padding-left: 26px;padding-top: 10px;" id='.$projname->Project_Id.'>Project:  '.$projname->Name.'</label> -->';
			if($_POST['type'] == 'repeated')
			{
				$recart.= $this->recart($projname->Project_Id);
			}elseif($_POST['type'] == 'purchase'){
				$recart.= $this->cart($projname->Project_Id);
			}elseif($_POST['type'] == 'work'){
				$recart.= $this->workorderscart($projname->Project_Id);
			}elseif($_POST['type'] == 'direct'){
				$recart.= $this->dirwrkcart($projname->Project_Id);
			}elseif($_POST['type'] == 'lease'){
				$recart.= $this->leaseorderscart($projname->Project_Id);
			}elseif($_POST['type'] == 'depatch'){
				$recart.= $this->despatchcart($projname->Project_Id);
			}else{
				
			}

	  		
	  		

	  	}
	  	$arr=array('recart'=>$recart,'error'=>'No');
  		return json_encode($arr);

	}

