	public function actionAddtocart()
	{
		$resourceid=$_POST['resource'];
		$jobcard=$_POST['jobcard'];
		$vendor=$_POST['vendorid'];
		$vendorrate=$_POST['vendorrate'];
		$model=New Cart();
		$cart = Cart::find()->where(['Resource_Id' => $resourceid])->andWhere(['Vendor_Id' => $vendor])->andWhere(['rate' => $vendorrate])->andWhere(['status' => 0])->one();

        
       	if($cart): 
       		$resource=Resources::findOne($resourceid);
       		$restypes=Resourcetype::findOne($resource->ResourceType_Id);
       		$restype=$restypes['Source_unit'];
       		if($restype==3):
				if($_POST['numworkers']!='' && $_POST['numdays']!=''):
					$qntyy = $_POST['numworkers'] * $_POST['numdays'];
					$quantity= $cart->Qnty + $qntyy;
				else:
					$quantity=$cart->Qnty + $_POST['resourceqty'];
					//$quantity=0;
				endif;
			else:
				$quantity=$cart->Qnty + $_POST['resourceqty'];
			endif;

			$cart->Qnty= $quantity; 
			$cart->EstresQnty= $quantity; 
			//$amount=$cart['rate'] * $cart->Qnty;
			if($quantity!=''){
				$amount=$vendorrate * $quantity;
			}
			else{
				$amount=0;
			}
			
			$cart->amount=$amount;
			$cart->place_status=1;


			if(isset($_POST['numworkers'])){
				if($_POST['numworkers']!=''){
					$cart->no_workers=$_POST['numworkers'];
				}
				if($_POST['numdays']!=''){
					$cart->no_days=$_POST['numdays'];
				}
				if($_POST['otrate']!=''){
					$cart->ot_rate=$_POST['otrate'];
				}
		  	}
			$cart->save(false);
	   	else:
			$model->Job_Id=$jobcard;
			$model->Vendor_Id=$vendor;
			$resource=Resources::findOne($resourceid); 
			$model->ResourceType_Id=$resource->ResourceType_Id;
			$model->Resource_Id=$resourceid;
			$model->unit=$resource->Unit;
			$model->rate=$vendorrate;
			$model->place_status=1;
			$jobcarddet=Jobcard::findOne($jobcard);
			$restypes=Resourcetype::findOne($resource->ResourceType_Id);
			$restype=$restypes['Source_unit'];
			if($restype==3):
				if($_POST['numworkers']!='' && $_POST['numdays']!=''):
					$quantity=$_POST['numworkers'] * $_POST['numdays'];
				else:
					$quantity=$_POST['resourceqty'];
					//$quantity=0;
				endif;
			else:
				$quantity=$_POST['resourceqty'];
			endif;
			$model->Qnty=$quantity;
			$model->EstresQnty=$quantity;
			if($quantity!=''){
				$amount=$vendorrate * $quantity;
			}
			else{
				$amount=0;
			}
			
			$model->amount=$amount;
			$userid = Yii::$app->user->id;
			$userproject = UserProjects::find()->where(['userid' => $userid])->one();
			if($jobcarddet){
				$model->Project=$jobcarddet['project_id'];
			}
			else{
				$model->Project=$userproject->projectid;
			}
			$model->groupid=$jobcarddet['groupid'];
			if(isset($_POST['numworkers'])){
				if($_POST['numworkers']!=''){
					$model->no_workers=$_POST['numworkers'];
				}
				if($_POST['numdays']!=''){
					$model->no_days=$_POST['numdays'];
				}
				if($_POST['otrate']!=''){
					$model->ot_rate=$_POST['otrate'];
				}
		  	}
			$model->save(false);
		endif;
		$jobcardmodel=Jobcard::findOne($jobcard); 
		if($jobcardmodel):
			$jobcardmodel->cart_status=1;
			$jobcardmodel->save(false);
		endif;

		$arr=array('result'=>$model->cartID,'error'=>'No');
	    return json_encode($arr);
   	}

	public function actionRemoveitem()
	{
		
      	$id=$_POST['id'];
	  	$model=Cart::findOne($id); 
      	$jobcards = Jobcard::find()->where(['resource' => $model['Resource_Id']])->andWhere(['cart_status' => 1])->all();	
      	$jobcardmodel=Jobcard::findOne($model['Job_Id']); 
		if($jobcardmodel):
			$jobcardmodel->cart_status=0;
			$jobcardmodel->save(false);
		endif;
		if($model->delete()):
			$arr = array('Id' => $id,'error'=>'No');
		else:
			$arr = array('Id' => $id,'error'=>'Yes','errortext'=>'Cannot remove.Please try again.');
		endif;
		return json_encode($arr);
	}

