	public function actionSendorderemail()
	{

		$order=Orders::findOne($_POST['orderid']);
		$bodytext=$_POST['body'];
		$subject=$_POST['subject'];
		$orderidd = $_POST['orderid'];
		$atta = Yii::$app->basePath . '/web/pdf/terms-and-conditions-' .$orderidd. '.pdf';
		$atta2 = Yii::$app->basePath . '/web/pdf/order-receipt-' .$orderidd. '.pdf';

		//if($atta !='' || $atta2 !=''){

		//echo file_exists($atta); exit;

		if(file_exists($atta2)!=''){
			$cars[] = $atta2;
		}

		if(file_exists($atta)!=''){
			$cars[] = $atta;
		}
	
		//$cars = array($atta2,$atta);
        $mail =  Yii::$app->mailer->compose('layouts/html', ['content' => $bodytext]); 
		$mail ->setFrom('procurement@geotech.net.in', 'Geotech');
        //$mail ->setFrom('vishnu@solminds.com', 'Geotech');
		$mail ->setTo($_POST['email']);
		if($_POST['ccemail']!=''){
			$ccemail = explode(',', $_POST['ccemail']);
			foreach ($ccemail as $email) {
				$mail ->setCc($email);
			}
		}

		$mail ->setSubject($subject);
		foreach ($cars as $file) {
			$mail->attach($file);
		}


		if(!$mail->send()) {
			if(file_exists($atta)!=''){
				unlink($atta);
			}
			if(file_exists($atta2)!=''){
				unlink($atta2);
			}
			$arr = array('error'=>'Yes','errortext'=>'Message could not be sent.Mailer Error: '.$mail->ErrorInfo.' ');
			return json_encode($arr);
		} else {
			$order->emailstatus=1;
			$order->status=2;
			$order->save(false);
			if(file_exists($atta)!=''){
				unlink($atta);
			}
			if(file_exists($atta2)!=''){
				unlink($atta2);
			}
			$arr = array('error'=>'No','errortext'=>'Message has been sent');
			return json_encode($arr);
		}

	//}



	}
	

