	public function actionPrintorder($id)
	{
		$order=Orders::findOne($id);
		$vendor=Vendors::findOne($order['vendor_id']);
		$connection = \Yii::$app->db;
		$sql="SELECT resource_id, COUNT(*) as count FROM ordered_resource where order_id=".$id." GROUP BY rate,resource_id HAVING COUNT(*) > 1";
		$command = $connection->createCommand($sql);
		$dataReader = $command->query();
		$dataProvider = $dataReader->read();

		$rcount = OrderedResource::find()->Where(['order_id'=>$id])->count();
		$ores = OrderedResource::find()->Where(['order_id'=>$id])->groupBy(['rate', 'resource_id'])->one();
		if($rcount > 1){
			if(!empty($ores)){
				//$resourceitems = OrderedResource::find()->Where(['order_id'=>$id])->andWhere(['group' => $ores->resource_id])->all();
				$resourceitems = OrderedResource::find()->Where(['order_id'=>$id])->all();
			}
		}else{
			$resourceitems = OrderedResource::find()->Where(['order_id'=>$id])->all();
		}

		if($order['order_type']==1):
			$type="PURCHASE ORDER";
		elseif($order['order_type']==2):
			$type="WORK ORDER";

			$activityNames=Jobcard::findOne($resourceitems[0]->jobcard_id); 
			$activityName=$activityNames['activity'];
		elseif($order['order_type']==3):
			$type="Direct Workers-Order";
			$jobcardid='';
			foreach($resourceitems AS $key=>$orderre):
				if($key==0):
					$jobcardid.=$orderre['jobcard_id'];
				else:
					$jobcardid.=",".$orderre['jobcard_id'];
				endif;
			endforeach;

			$activityNames=Jobcard::find()->where(['in','job_id',$jobcardid])->one();
            $activityName = $activityNames['activity'];

