	public function Createjournalfun($crordertype,$crvendor,$crinvoices,$crproject,$crorders,$creditvendors)
    {
        if($crordertype==1 || $crordertype==3):
            $ordertype="Invoice";
            $invoice=Invoice::find()->where(['in','invoice_id',$crinvoices])->all();
        else:
            $ordertype="Workorder";
            $invoice=WorkorderBills::find()->where(['in','bill_id',$crinvoices])->andWhere(['delete_status' => 0])->all();
        endif;
        //echo count($invoice);exit;
        $connection = \Yii::$app->db;
        $userid=Yii::$app->user->id;
        $user=User::findOne($userid);
        if($user['superuser']==1 || $user['superuser']==2)
        {
            $sql="select * from projects WHERE Project_Delete_Status=0";
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
            $adminprojects=$dataReader->readAll();
        }
        else
        {
            $sql="select a.projectid,b.Name from user_projects as a inner join projects as b on a.projectid=b.Project_Id where userid='$userid'";
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
            $userprojects=$dataReader->readAll();
        }
        if($ordertype=='Workorder'):
            $projectids=$invoice[0]['place'];
        else:
            $projectids=$invoice[0]['project_id'];
        endif;
        if($ordertype=='Workorder'):
            $invoiceid=$crinvoices;
            $sql="SELECT resource_acnt, COUNT(*) as count FROM workorder_items where bill_id IN (".$invoiceid.") AND delete_status=0 GROUP BY resource_acnt HAVING COUNT(*) > 1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $dataProvider = $dataReader->read();
            if(empty($dataProvider)):
                $orderres=WorkorderItems::find()->where(['in','bill_id',$invoiceid])->andWhere(['delete_status' => 0])->all();
            else:
                $orderres=WorkorderItems::find()->where(['in','bill_id',$invoiceid])->andWhere(['delete_status' => 0])->groupBy(['resource_acnt'])->all();
            endif;
        else:
            $invoiceid=$crinvoices;
            $sql="SELECT resource_acnt, COUNT(*) as count FROM invoice_resources where invoice_id IN (".$invoiceid.") GROUP BY resource_acnt HAVING COUNT(*) > 1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $dataProvider = $dataReader->read();
            //echo $sql;exit;
            //echo $dataProvider['count'];exit;
            if(empty($dataProvider)):
                $orderres=InvoiceResources::find()->where(['in','invoice_id',$invoiceid])->all();
            else:
