                $debittotal+=$debitamount;
                $res_details=Resources::findOne($resource['resource_id']);
                $resacntid=$res_details['Resource_Acc_Id'];
                $acnts=AccountsItem::find()->orderBy(['name' => SORT_ASC])->all();
