                    endif;
                endforeach;
                //$sql="INSERT INTO journalitems(journalid,debitaccnt,amount,narration) values ('".$model->id."','".$resacntid."','".$debitamount."','".$narration."')";
                $sql='INSERT INTO journalitems(journalid,debitaccnt,amount,narration) values ("'.$model->id.'","'.$resacntid.'","'.$debitamount.'","'.$narration.'")';
                //echo $sql;
                $command=$connection->createCommand($sql);
                $dataReader=$command->query();

                //trpamout entry
                $ordervalues=Orders::find()->where(['in','order_id',$crorders])->all();
                $tottp=0;
                foreach($ordervalues AS $ordervalue):
                    $tottp+=$ordervalue['transportation'];
                endforeach;
                if($tottp!=0){
                    $trpaccount = AccountsItem::find()->where(['like','name','Transportation Charges'])->one();
                    $sql="INSERT INTO journalitems(journalid,debitaccnt,amount,narration) values ('".$model->id."','".$trpaccount->id."','".$tottp."','".'Transportation Charges'."')";
