                }
                //trpamout entry-END

                if($gstdet['cgst']!=0):
                    $productcgst = OrderedResource::find()->where(['in','order_id',$crorders])->max('cgst');
                    $gstamount=($debittotal * $productcgst) / 100;
                    $totalamount=($debittotal) + ($gstamount * 2);

                    $newnarration = 'Being Input CGST @ '.$productcgst.' %';

                    $sql="INSERT INTO journalitems(journalid,debitaccnt,amount,narration) values ('".$model->id."','498','".$gstamount."','".$newnarration."')";
                    //echo $sql;
                    $command=$connection->createCommand($sql);
                    $dataReader=$command->query();

                    $newnarration = 'Being Input SGST @ '.$productcgst.' %';

                    $sql="INSERT INTO journalitems(journalid,debitaccnt,amount,narration) values ('".$model->id."','499','".$gstamount."','".$newnarration."')";
                    //echo $sql;
                    $command=$connection->createCommand($sql);
                    $dataReader=$command->query();

                elseif($gstdet['igst']!=0):
