	public function actionTermsandconditions($id)
	{
		//$order=Orders::model()->findByPk($id);

		$order=Orders::findOne($id); 
		//$terms=Drawings::model()->findByPk($order['terms']);
		$terms=Drawings::findOne($order['terms']);

		$extension=$this->getExtendion($terms['filename']);
		//echo $extension;exit;
		if($extension=='doc'):
			$this->redirect("https://docs.google.com/gview?url=http://www.geotech.net.in/app/".$terms['filename']."");
		else:
			return $this->redirect(Yii::app()->request->baseUrl."/".$terms['filename']."");
		endif;
	}

	public function getExtendion($file)
	{
		/*
         * "." for extension should be available and not be the first character
         * so position should not be false or 0.
         */
		$lastDotPos = strrpos($file, '.');

		if ( !$lastDotPos ){
			return false;
		}
		else{
			$exten=substr($file, $lastDotPos+1);
			$type='';
			switch($exten){
				case 'jpg':
					$type='image';
					break;
				case 'jpeg':
					$type='image';
					break;
				case 'png':
					$type='image';
					break;
				case 'gif':
					$type='image';
					break;
				case 'pdf':
					$type='pdf';
					break;
				default:
					$type='doc';
					break;
			}
			return $type;
		}
	}

	public function actionCancelorder()
	{

		$invoices=Invoice::find()->where(['order_id' => $_POST['orderid']])->one();  

		if($invoices):

			$arr = array('Id' => $_POST['orderid'],'error'=>'Yes','errortext'=>'Can not Cancel this Order as it is associate with an Invoice');

			return json_encode($arr);

		else:

			$order=Orders::findOne($_POST['orderid']); 

            $orderres=OrderedResource::find()->Where(['order_id'=>$_POST['orderid']])->all();

            if($orderres):

            	foreach($orderres AS $resource):

				 	//$cart=Cart::deleteAll(['Job_Id' => $resource->jobcard_id, 'Resource_Id' => $resource->resource_id,'status'=>1]);

				 	$cart = Cart::find()->where(['Job_Id'=>$resource->jobcard_id])->one();
				 	$cart->status=0;
	                $cart->save(false);

					$jobcard=Jobcard::find()->where(['job_id' => $resource->jobcard_id])->one();
					if($jobcard):
		                //$jobcard->cart_status=0;
		                $jobcard->cart_status=1;
		                $jobcard->save(false);
		            endif;

				endforeach;

            endif;

			$orderres=OrderedResource::findOne(['order_id'=>$_POST['orderid']]);

            $orderres->delete_status=1;
            $orderres->save(false);

			$order->des_status=1;
			$order->delete_status=1;
			$order->date=date('Y-m-d');
			$order->save(false);
			
$uid = Yii::$app->user->Id;

			$placeorderstatus = new PlaceorderStatus();
            $placeorderstatus->order_id = $_POST['orderid'];
            $placeorderstatus->cancelled_by = $uid;
            $placeorderstatus->cancelled_date = date("Y-m-d H:i:s");
            $placeorderstatus->save(false);

 

			$arr=array('result'=>$_POST['orderid'],'error'=>'No');
			return json_encode($arr);
		endif;
	}

