	public function getfolderids()
	{
		$ids='';

       	$folders=Folders::find()->Where(['LIKE', 'name', "%terms and conditions%"])->all();

		if($folders):
			foreach($folders AS $key=>$folder):
				if($key==0):
					$ids.=$folder['ID'];
				else:
					$ids.=",".$folder['ID'];
				endif;
			endforeach;
		endif;
		return $ids;

	}
	
