     public function equipmentamount($activityid,$resourceid,$projectid)
    {
    	//echo $activityid;exit;
    	$connection = \Yii::$app->db;
        $sql = "SELECT *  FROM `resources` WHERE `Resource_Id` = ".$resourceid." AND pricing_status=0";
        //echo $sql;exit;
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $prestimateitem=$dataReader->read();
        //print_r($prestimateitem);exit;
        $resourcename=$prestimateitem['Name'];


        //if(count($prestimateitem)>0){
            //$sql ="SELECT sum(diesel) as dieselissued, sum(worked_hours) as workedhours FROM logbook WHERE equipment_id =".$resourceid." ";
            $sql ="SELECT * FROM logbook WHERE equipment_id =".$resourceid." AND activity_id =".$activityid."";
            //echo $sql;exit;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $equipment = $dataReader->read();
            $units='';
            if($equipment){
            	$units=	$equipment['unit'];
            	if($equipment['start_time_km']!='' && $equipment['end_time_km']!=''){
                	$totunitswrkd = $equipment['end_time_km']-$equipment['start_time_km'];
	            }
	            else{
	                $totunitswrkd ='';               
	            }
	            if($equipment['trips']!='')
	            {
	            	$trips=$equipment['trips'];
	            }
	            else{
	            	$trips='';
	            }
	        }
    //}
        else{
            $totunitswrkd ='';
            $trips='';
        }


        $sql = "SELECT log_hours,log_consumption FROM `electrical_logbook` WHERE `log_resource` = ".$resourceid." AND log_project=".$projectid." ";
        //echo $sql;exit;
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $currreportdata=$dataReader->read();
        //print_r($currreportdata);exit;
        if(!empty($currreportdata)){
            if($currreportdata['log_hours']!=0):
                $currenthours=$currreportdata['log_hours'];
            else:
                $currenthours='';
            endif;
             if($currreportdata['log_consumption']!=0):
                $powerused=$currreportdata['log_consumption'];
            else:
                $powerused='';
            endif;
        }else{
        	$currenthours='';
            $powerused='';
        }





        $sql = "SELECT *  FROM `resources` WHERE `Name` LIKE 'Diesel' AND pricing_status=0";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
