    	}elseif($_POST['reqty']!=''){
    		
    		$cart->Qnty = $_POST['reqty'];
    	
    		$amount = $cart->rate * $_POST['reqty'];
    		
    	}elseif($_POST['rate']!=''){
    		

    		$cart->rate = $_POST['rate'];
    		$amount = $_POST['rate'] * $cart->EstresQnty;

    	}else{

    		$cart->Qnty = 0;
    		
    		$amount = $cart->rate * $cart->EstresQnty;

    	}
    	$cart->amount= $amount;
    	$cart->save(false);
        
        $reamount = number_format($amount,2);

    	$jobcard=Jobcard::findOne($cart->Job_Id);
    	$jobcard->res_quantity = $_POST['reqty'];
    	$jobcard->res_rate = $_POST['rate'];
    	$jobcard->save(false);

    	$placeorderes = PlaceorderRes::find()->where(['cartID' => $cart->cartID])->andWhere(['Vendor_Id' => $cart->Vendor_Id])->andwhere(['Resource_Id' =>$cart->Resource_Id])->andWhere(['Project' =>$cart->Project])->one();

    	if(empty($placeorderes)){
    		$model = new PlaceorderRes();
    		$model->cartID = $cart->cartID;
    		$model->Job_Id = $cart->Job_Id;
    		$model->Vendor_Id = $cart->Vendor_Id;
    		$model->Resource_Id = $cart->Resource_Id;
    		$model->Project = $cart->Project;
    	}
    	else{
    		$model = PlaceorderRes::findOne($placeorderes->id);
    	}
    	
    	if(isset($_POST['reqty'])){
    		$model->req_qty = $_POST['reqty'];
    	}
    	if(isset($_POST['reordqty'])){

    		$model->reorderqty = $_POST['reordqty'];
    	}
    	if(isset($_POST['reorderlevel'])){
    		$model->reorder_level = $_POST['reorderlevel'];
    	}
    	
    	$model->save(false);

    	$alljobcards = Jobcard::find()->where(['resource' => $model->Resource_Id])->andWhere(['app_activity' => $jobcard->app_activity])->andWhere(['cart_status' => 1])->andWhere(['delete_status' => 0])->all();

		$oldissueslipstotal = 0;

		foreach($alljobcards as $alljobcard):

			$jobplaceorderes = PlaceorderRes::find()->where(['Job_Id' => $alljobcard->job_id])->andwhere(['Resource_Id' =>$alljobcard->resource])->andWhere(['Project' =>$alljobcard->project_id])->one();

			if($jobplaceorderes){

				$oldissueslipstotal = $oldissueslipstotal + $jobplaceorderes->req_qty;

			}

		endforeach;

		$remaining1 = number_format($oldissueslipstotal,2);

		$remaining = $cart->EstresQnty - $remaining1;

    	$venresourcetotal = Cart::find()->where(['status'=>0])->andWhere(['Project'=>$cart->Project])->andWhere(['Vendor_Id'=>$cart->Vendor_Id])->sum('amount');

    	$totalamt = number_format($venresourcetotal,2);

    	if($_POST['reqty']==''){
