    	}

    	$arr=array('error'=>'No','totalamt'=>$totalamt,'amount'=>$reamount,'remaining'=>$remaining,'vendorid'=>$cart->Vendor_Id,'amnt'=>$amount);
    	return json_encode($arr);

    }
