	public function actionChangevendor()
	{
		//echo 'hai'; exit;

		$cart= Cart::findOne($_POST['cartid']); 
		$resource=Resources::findOne($_POST['resourceid']);

		if($_POST['splitqty']=='' || $_POST['splitqty'] == $_POST['requiedqty']){


			$existcart = Cart::find()->where(['Resource_Id' => $_POST['resourceid']])->andWhere(['Vendor_Id' => $_POST['vendorid']])->andWhere(['Project' => $cart->Project])->andWhere(['status' => 0])->one();

			if($existcart){

				$cart->status = 5;
				$cart->save(false);

				$finalqty = $cart->Qnty + $existcart->Qnty;
				$amount= $resource->Price * $finalqty;
				$existcart->Qnty = $finalqty;
				$existcart->amount=$amount;

				if($existcart->save(false)):

					$jobcard= Jobcard::findOne($existcart->Job_Id); 
					$jobcard->res_quantity=$existcart->Qnty;
					if($jobcard->save(false)):

						$placeorderes = PlaceorderRes::find()->where(['cartID' => $existcart->cartID])->andWhere(['Job_Id' => $existcart->Job_Id])->andWhere(['Project' =>$existcart->Project])->orderBy(['id'=> SORT_DESC])->one();
						if($placeorderes){
							$placeorderes->req_qty=$existcart->Qnty;
							$placeorderes->save(false);
						}

					endif;

				endif;

			}
			else{

				$cart->Vendor_Id=$resource->Vendor_Id; 
				$cart->ResourceType_Id=$resource->ResourceType_Id;
				$cart->Resource_Id=$resource->Resource_Id;
				$cart->unit=$resource->Unit;
				$cart->rate=$resource->Price;  
				$amount= $resource->Price * $cart->Qnty;
				$cart->amount=$amount;
				if($cart->save(false)):

					$jobcard= Jobcard::findOne($cart->Job_Id); 
					$jobcard->resource=$cart->Resource_Id;
					$jobcard->res_rate=$cart->rate;
					$jobcard->unit=$cart->unit;
					$jobcard->vendor_id=$cart->Vendor_Id;
					if($jobcard->save(false)):

						$placeorderes = PlaceorderRes::find()->where(['cartID' => $cart->cartID])->andWhere(['Job_Id' => $cart->Job_Id])->andWhere(['Project' =>$cart->Project])->orderBy(['id'=> SORT_DESC])->one();
						if($placeorderes){
							$placeorderes->Vendor_Id=$cart->Vendor_Id;
							$placeorderes->Resource_Id=$cart->Resource_Id;
							$placeorderes->save(false);
						}

					endif;

				endif;

			}

		}
		else{
			$oldcartqty = $cart->Qnty - $_POST['splitqty'];
			$cart->Qnty = $oldcartqty;  
			$amount= $cart->rate * $oldcartqty;
			$cart->amount=$amount;
			if($cart->save(false)):

				$jobcard= Jobcard::findOne($cart->Job_Id); 
