				$cart->Vendor_Id=$resource->Vendor_Id; 
				$cart->ResourceType_Id=$resource->ResourceType_Id;
				$cart->Resource_Id=$resource->Resource_Id;
				$cart->unit=$resource->Unit;
				$cart->rate=$resource->Price;  
				$amount= $resource->Price * $cart->Qnty;
				$cart->amount=$amount;
				if($cart->save(false)):

					$jobcard= Jobcard::findOne($cart->Job_Id); 
					$jobcard->resource=$cart->Resource_Id;
					$jobcard->res_rate=$cart->rate;
					$jobcard->unit=$cart->unit;
					$jobcard->vendor_id=$cart->Vendor_Id;
					if($jobcard->save(false)):

						$placeorderes = PlaceorderRes::find()->where(['cartID' => $cart->cartID])->andWhere(['Job_Id' => $cart->Job_Id])->andWhere(['Project' =>$cart->Project])->orderBy(['id'=> SORT_DESC])->one();
						if($placeorderes){
							$placeorderes->Vendor_Id=$cart->Vendor_Id;
							$placeorderes->Resource_Id=$cart->Resource_Id;
							$placeorderes->save(false);
						}

					endif;

				endif;

			}

		}
		else{
			$oldcartqty = $cart->Qnty - $_POST['splitqty'];
			$cart->Qnty = $oldcartqty;  
			$amount= $cart->rate * $oldcartqty;
			$cart->amount=$amount;
			if($cart->save(false)):

				$jobcard= Jobcard::findOne($cart->Job_Id); 
				$jobcard->res_quantity=$cart->Qnty;
				if($jobcard->save(false)):

					$placeorderes = PlaceorderRes::find()->where(['cartID' => $cart->cartID])->andWhere(['Job_Id' => $cart->Job_Id])->andWhere(['Project' =>$cart->Project])->orderBy(['id'=> SORT_DESC])->one();
					if($placeorderes){
						$placeorderes->req_qty=$cart->Qnty;
						if($placeorderes->save(false)):

							$connection = \Yii::$app->db;
	                        $sql="SELECT name FROM jobcard ORDER BY name DESC limit 1";
	                        $command=$connection->createCommand($sql);
	                        $dataReader=$command->query();
	                        $no=$dataReader->read();
	                        $name=$no['name'] + 1;
	                        $groupid=time();

	                        $Jobcard = New Jobcard();
	                        $Jobcard->name= $name;
	                        $Jobcard->date= date('Y-m-d');
	                        $Jobcard->process= $jobcard->process;
	                        $Jobcard->activity= $jobcard->activity;
	                        $Jobcard->groupid= $groupid;
	                        $Jobcard->project_id= $jobcard->project_id;
	                        $Jobcard->resource= $resource->Resource_Id;
	                        $Jobcard->unit= $resource->Unit;
	                        $Jobcard->res_quantity= $_POST['splitqty'];
	                        $Jobcard->res_rate= $resource->Price;
	                        $Jobcard->est_resqty= $jobcard->est_resqty;
	                        $Jobcard->vendor_id= $resource->Vendor_Id;
	                        $Jobcard->user_id= $jobcard->user_id;
	                        $Jobcard->app_activity= $jobcard->app_activity;
	                        $Jobcard->iow= $jobcard->iow;
	                        $Jobcard->status= 1;
	                        $Jobcard->parent_jobcard_id= $jobcard->job_id;
	                        //$Jobcard->save(false);

	                        if($Jobcard->save(false)):

	                            $model=New Cart();

	                            $model->Job_Id= $Jobcard->job_id;
	                            $model->Vendor_Id= $Jobcard->vendor_id;
	                            $model->ResourceType_Id= $resource->ResourceType_Id;
	                            $model->Resource_Id= $Jobcard->resource;
	                            $model->unit= $Jobcard->unit;
	                            $model->rate= $Jobcard->res_rate;
	                            $model->Qnty= $_POST['splitqty'];
	                            $model->EstresQnty= $Jobcard->est_resqty;
	                            $amount = $_POST['splitqty'] * $Jobcard->res_rate;
	                            $model->amount= $amount;
	                            $model->Project= $Jobcard->project_id;
	                            $model->groupid= $Jobcard->groupid;
	                            if($model->save(false)):

	                            	$newplaceordr = new PlaceorderRes();
						    		$newplaceordr->cartID = $model->cartID;
						    		$newplaceordr->Job_Id = $model->Job_Id;
						    		$newplaceordr->Vendor_Id = $model->Vendor_Id;
						    		$newplaceordr->Resource_Id = $model->Resource_Id;
						    		$newplaceordr->Project = $model->Project;
						    		$newplaceordr->req_qty = $_POST['splitqty'];
							    	$newplaceordr->reorderqty = $placeorderes->reorderqty;
							    	$newplaceordr->reorder_level = $placeorderes->reorder_level;
							    	$newplaceordr->save(false);

	                            endif;

	                            $Jobcard->cart_status=1;
	                            $Jobcard->save(false);

	                        endif;

						endif;
					}

				endif;

			endif;

		}

		$arr=array('error'=>'No');
		return json_encode($arr);
	}

