    public function actionProjectsearch()
    {
         $connection = \Yii::$app->db; 
         $uid = Yii::$app->user->Id; 
        $row = User::findOne($uid);
        $roleid = $row->superuser;

        if ($roleid==1) {
            $sql = "SELECT Project_Id,Name,duration,project_value,client_name FROM projects where status='0' AND Project_Delete_Status='0' AND favourite=1 ORDER BY Project_Id ASC, Name ASC ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $dataProvider = $dataReader->readAll();
        } else {
            $sql = "SELECT a.Project_Id,a.Name,a.duration,a.project_value,a.client_name FROM projects as a inner join user_projects as b on a.Project_Id=b.projectid where b.userid='$uid' and status='0' AND Project_Delete_Status='0' AND favourite=1 ORDER BY Project_Id ASC, Name ASC ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $dataProvider = $dataReader->readAll();
        }


        $datarows = '';

        if($row->role_id != 0)
        {

            $assignedprojects =  UserProjects::find()->where(['userid'=>$uid])->all();
            if(count($assignedprojects)>0)
            {
                foreach($assignedprojects as $usprojects){
                    $projs = Projects::findOne($usprojects->projectid);

                $days = $projs->duration;
                if($projs->duration!=0){

                $years = intval($days / 365); 
                $days = $days % 365;
                $months = intval($days / 30); 
                $days = $days % 30;
                $prjctdate = $years.' years '.$months.' months '.$days.' days';

                }
                else{
                $prjctdate = '0 years 0 months 0 days';
                }

                    $datarows .= '<div class="col-md-4" id="project'.$usprojects->projectid.'">';
                    $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
                    if($projuser && $projuser->projectid==$usprojects->projectid){

                            $datarows .= '<div data-id="'.$usprojects->projectid.'" class="rprojectselection fav-project-wrpr card active">';
                    }
                    else
                    {
                        $datarows .= '<div data-id="'.$usprojects->projectid.'" class="rprojectselection fav-project-wrpr card">';

                    }

                     $datarows .= '<div class="card-body">
                                            <a href="#"><span class="icon-check"></span>'. $projs->Name.'</a>
                                        </div>
                                        <div class="card-footer">
                                            
                                            <div class="row">
                                                <div class="col-md-12">
                                                    <div class="type project-client-name">
                                                        <label>Client</label>
                                                        <span>'.$projs->client_name.'</span>
                                                    </div>
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="type">
                                                        <label>Project Duration</label>
                                                        <span>'.$prjctdate.'</span>
                                                    </div>
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="type text-right">
                                                        <label>Project Value</label>
                                                        <span>'. $projs->project_value.'</span>
                                                    </div>
                                                </div>
                                            </div>
                                            
                                        </div>
                                    </div>
                                </div>';



                }

            }else{
                $datarows = '<tr id="nodata"><td colspan="13" style="text-align: center;">No Projects Found</td></tr>';
            }
            

        }else{

            if (count($dataProvider) > 0):
            foreach ($dataProvider AS $key => $data):

                $days = $data['duration'];
                if($data['duration']!=0){

                $years = intval($days / 365); 
                $days = $days % 365;
                $months = intval($days / 30); 
                $days = $days % 30;
                $prjctdate = $years.' years '.$months.' months '.$days.' days';

                }
                else{
                $prjctdate = '0 years 0 months 0 days';
                }
                $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
                $datarows .= '<div class="col-md-4" id="project'.$data['Project_Id'] .'">';

                if($projuser && $projuser->projectid==$data['Project_Id']){

                            $datarows .= '<div data-id="'.$data['Project_Id'] .'" class="rprojectselection fav-project-wrpr card active">';
                    }
                    else
                    {
                        $datarows .= '<div data-id="'.$data['Project_Id'] .'" class="rprojectselection fav-project-wrpr card">';

                    }

                            $datarows .= '<div class="card-body">
                                            <a href="#"><span class="icon-check"></span>'. $data['Name'].'</a>
                                        </div>
                                        <div class="card-footer">
                                            
                                            <div class="row">
                                                <div class="col-md-12">
                                                    <div class="type project-client-name">
                                                        <label>Client</label>
                                                        <span>'.$data['client_name'].'</span>
                                                    </div>
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="type">
                                                        <label>Project Duration</label>
                                                        <span>'.$prjctdate.'</span>
                                                    </div>
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="type text-right">
                                                        <label>Project Value</label>
                                                        <span>'. $data['project_value'].'</span>
                                                    </div>
                                                </div>
                                            </div>
                                            
                                        </div>
                                    </div>
                                </div>';
            endforeach;

        else:
            $datarows = '<tr id="nodata"><td colspan="13" style="text-align: center;">No Projects Found</td></tr>';
        endif;


        }
        
        $arr = array('result' => $datarows,'projectinfo' => $datarows, 'error' => 'No');
        return json_encode($arr);
    }

